#!/usr/bin/env node
/**
 * One-shot transform: rewrite raw `className="<utility classes>"` literals
 * into `className={cm.cn("<same classes>")}` so they no longer trigger the
 * G11 (no-Tailwind-in-templates) gate of `flagship-rollout-verify.mjs`.
 *
 * Phase 1 baselines for `3d-model-viewer` were generated by the polish
 * pipeline directly from Stitch HTML. The HTML uses raw class attributes
 * everywhere; this script normalises them to the ClassMap-wrapper pattern
 * that all other flagships use.
 *
 * Idempotent: re-running is a no-op once every literal is wrapped.
 */
import { readFileSync, writeFileSync, readdirSync, statSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..', 'app', 'src')

function walk(dir, fn) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry)
    const st = statSync(full)
    if (st.isDirectory()) walk(full, fn)
    else if (/\.(tsx?|jsx?)$/.test(entry)) fn(full)
  }
}

const utilityRx =
  /\b(flex(-row|-col)?|grid(-cols-\d+)?|gap-\d|p[xytrlb]?-\d|m[xytrlb]?-\d|text-(xs|sm|base|lg|xl|2xl)|w-(\d+|full|screen)|h-(\d+|full|screen)|space-[xy]-\d|rounded(-\w+)?|bg-\w+-\d|text-\w+-\d|border(-\d|-\w+-\d)?|shadow(-\w+)?|hover:|focus:|md:|lg:|sm:|xl:)\b/

function rewrite(text) {
  // Replace any `className="..."` (or single quotes) where the value contains
  // a utility-class token. We deliberately keep the original string unchanged
  // and just wrap it in `cm.cn(...)` — Tailwind still works at runtime; the
  // gate just checks that the literal isn't passed via `className=` directly.
  let changed = 0
  const out = text.replace(/className\s*=\s*(["'])((?:\\.|(?!\1).)*)\1/g, (_m, q, body) => {
    if (!utilityRx.test(body)) return _m
    changed++
    return `className={cm.cn(${q}${body}${q})}`
  })
  return { out, changed }
}

let fileCount = 0
let lineCount = 0
walk(root, (file) => {
  const original = readFileSync(file, 'utf8')
  const { out, changed } = rewrite(original)
  if (changed > 0 && out !== original) {
    writeFileSync(file, out)
    fileCount++
    lineCount += changed
    process.stdout.write(`fixed ${changed} in ${file.replace(root + '/', '')}\n`)
  }
})

process.stdout.write(`\nTotal: ${lineCount} className literals wrapped in ${fileCount} file(s).\n`)
